  --color-primary-100: #09479E;  /* B75 */
  --color-primary-200: #1D7AFC;  /* B200 */
  --color-primary-300: #388BFF;  /* B300 — primary action */
  --color-primary-400: #4C9AFF;  /* B400 */
  --color-primary-500: #579DFF;  /* B500 — accent on dark */
  --color-primary-600: #85B8FF;  /* B600 — subtle 텍스트 */
  --color-primary-700: #A6C5FF;
  --color-primary-800: #CCE0FF;
  --color-primary-900: #E9F2FF;

  /* Secondary - Purple */
  --color-secondary-500: #9F8FEF;

  /* Neutral - Atlassian dark neutral scale (반전 램프) */
  --color-neutral-0:    #161A1D;  /* 가장 어두운 캔버스 */
  --color-neutral-50:   #1D2125;  /* N20 — base surface */
  --color-neutral-100:  #282E33;  /* N30 — raised surface */
  --color-neutral-200:  #38414A;  /* N40 — border default */
  --color-neutral-300:  #454F59;  /* N60 — border strong */
  --color-neutral-500:  #738496;  /* N200 — muted text/icon */
  --color-neutral-700:  #8C9BAB;  /* N300 */
  --color-neutral-800:  #B6C2CF;  /* N400 — secondary text */
  --color-neutral-900:  #DEE4EA;  /* N800 — text primary */
  --color-neutral-1000: #E6EDF3;  /* N900 — 최강조 텍스트 */

  /* Semantic (다크 표면 위 가독성 튜닝) */
  --color-success-bg: #143C2C;
  --color-success-fg: #7EE2B8;
  --color-warning-bg: #4A3408;
  --color-warning-fg: #F5CD47;
