  --color-neutral-100:  #EBECF0;  /* N30 */
  --color-neutral-200:  #DFE1E6;  /* N40 */
  --color-neutral-300:  #C1C7D0;  /* N60 */
  --color-neutral-500:  #7A869A;  /* N200 */
  --color-neutral-700:  #5E6C84;  /* N300 */
